/**
 * Real payloads, copied verbatim from real runs.
 *
 * Not generated by `make fixtures` — a payload is what a run PRODUCED, and the
 * only way to get one is to run the pipe. Each was produced by the matching pipe
 * in `data/structures/results.mthds` through `pipelex run bundle` against the
 * default deck on 2026-08-31, from one shared note:
 *
 *   "Invoice INV-2026-0042 for Acme Logistics, issued 14 March 2026, still
 *    unpaid. Lines: design retainer, 1 unit at 1200.00 EUR; additional
 *    revisions, 4 units at 160.13 EUR. Total 1840.50 EUR. The client was
 *    delighted with the turnaround."
 *
 * They are pasted UNEDITED, including the two shapes that are easy to get wrong
 * and that no amount of reading the descriptor would have revealed:
 *
 *  - a `date` arrives as kajson's typed form, `{date, __class__, __module__}`,
 *    not as a bare ISO string;
 *  - a plural output's payload is `{ items: [...] }`, not a bare array — the
 *    list content model wraps, exactly as a scalar content model does.
 *
 * Both are why these live here rather than being written by hand from the
 * descriptor: a hand-written payload would have been a bare string and a bare
 * array, and the renderer would have been built to a shape that never occurs.
 */

/** `results.flat_result` → `Sentiment`. */
export const FLAT_RESULT = {
  label: 'neutral',
  confidence: 0.7,
  rationale:
    'The note is largely factual and administrative — detailing an unpaid invoice with line items and amounts. However, it contains one positive element: "The client was delighted with the turnaround." This single upbeat remark is outweighed by the neutral/negative context of an overdue payment, resulting in an overall neutral sentiment.',
};

/** `results.nested_result` → `Invoice`, which carries a date and a list of concepts. */
export const NESTED_RESULT = {
  reference: 'INV-2026-0042',
  issued_on: { date: '2026-03-14', __class__: 'date', __module__: 'datetime' },
  total: 1840.5,
  paid: false,
  lines: [
    { label: 'design retainer', quantity: 1, unit_price: 1200.0 },
    { label: 'additional revisions', quantity: 4, unit_price: 160.13 },
  ],
};

/** `results.plural_result` → `LineItem[]`. Note the `items` wrapper. */
export const PLURAL_RESULT = {
  items: [
    { label: 'design retainer', quantity: 1, unit_price: 1200.0 },
    { label: 'additional revisions', quantity: 4, unit_price: 160.13 },
  ],
};

/** `results.plain_text_result` → `Text`, whose content model wraps under `text`. */
export const PLAIN_TEXT_RESULT = {
  text: 'Acme Logistics was invoiced 1840.50 EUR on 14 March 2026; the invoice is unpaid.',
};
